<script>const roles=document.getElementById('rol'), branches=document.getElementById('sucursales'); function sync(){const cashier=roles.selectedOptions[0]?.dataset.cajero==='1'; branches.multiple=!cashier; branches.required=cashier; if(cashier&&branches.selectedOptions.length>1)[...branches.options].forEach((o,i)=>o.selected=i===[...branches.options].findIndex(x=>x.selected)); document.getElementById('sucursal-label').textContent=cashier?'Sucursal asignada *':'Sucursales autorizadas'} roles.addEventListener('change',sync); sync();</script>
